 "<div style=\"font-family:'Playfair Display', serif;font-size:21px;font-weight:700\"><span lang=\"de\" translate=\"no\">der Adventskranz</span></div><div style=\"font-size:16px;color:#6b5a3a\">corona de Adviento</div>": "<div style=\"font-family:'Playfair Display', serif;font-size:21px;font-weight:700\"><span lang=\"de\" translate=\"no\">der Adventskranz</span></div><div style=\"font-size:16px;color:#6b5a3a\">Kranz mit vier Kerzen</div>",
